const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Trent River area in the UK (approximate polygon)
  const trentRiver = ee.Geometry.Polygon([
    [[-0.8, 53.0], [-0.6, 53.0], [-0.6, 53.2], [-0.8, 53.2], [-0.8, 53.0]]
  ]);

  // Date ranges
  const baselineStart = '2017-08-01';
  const baselineEnd = '2017-08-14';
  const eventStart = '2017-09-15';
  const eventEnd = '2017-09-20';

  // 2. Data Acquisition - Sentinel-1 GRD
  // Function to filter and preprocess Sentinel-1
  function getSARCollection(startDate, endDate) {
    return ee.ImageCollection('COPERNICUS/S1_GRD')
      .filterBounds(trentRiver)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.eq('instrumentMode', 'IW'))
      .filter(ee.Filter.eq('orbitProperties_pass', 'DESCENDING')) // Consistent orbit
      .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
      .select(['VV']);
  }

  // Get collections
  let baselineCol = getSARCollection(baselineStart, baselineEnd);
  let eventCol = getSARCollection(eventStart, eventEnd);

  // Check for empty collections
  const baselineSize = baselineCol.size().getInfo();
  const eventSize = eventCol.size().getInfo();

  console.log(`Baseline images (Aug 1-14): ${baselineSize}`);
  console.log(`Event images (Sep 15-20): ${eventSize}`);

  // Handle Case 1: Empty Collection
  if (baselineSize === 0 || eventSize === 0) {
    console.log("Empty collection detected. Trying ascending orbit as fallback...");
    // Try ascending orbit
    baselineCol = ee.ImageCollection('COPERNICUS/S1_GRD')
      .filterBounds(trentRiver)
      .filterDate(baselineStart, baselineEnd)
      .filter(ee.Filter.eq('instrumentMode', 'IW'))
      .filter(ee.Filter.eq('orbitProperties_pass', 'ASCENDING'))
      .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
      .select(['VV']);
    eventCol = ee.ImageCollection('COPERNICUS/S1_GRD')
      .filterBounds(trentRiver)
      .filterDate(eventStart, eventEnd)
      .filter(ee.Filter.eq('instrumentMode', 'IW'))
      .filter(ee.Filter.eq('orbitProperties_pass', 'ASCENDING'))
      .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
      .select(['VV']);

    const baselineSize2 = baselineCol.size().getInfo();
    const eventSize2 = eventCol.size().getInfo();
    console.log(`Baseline images (ascending): ${baselineSize2}`);
    console.log(`Event images (ascending): ${eventSize2}`);

    if (baselineSize2 === 0 || eventSize2 === 0) {
      console.log("Insufficient SAR data for analysis.");
      console.log("<answer>C1</answer>");
      return;
    }
  }

  // 3. Processing - Create median composites and water masks
  // Water detection threshold: VV < -15 dB (typical for open water)
  const waterThreshold = -15;

  const baselineImg = baselineCol.median();
  const eventImg = eventCol.median();

  // Create water masks (1 = water, 0 = non-water)
  const baselineWater = baselineImg.lt(waterThreshold);
  const eventWater = eventImg.lt(waterThreshold);

  // 4. Calculate water area in square km
  // Pixel area in square meters (Sentinel-1 resolution ~10m)
  const pixelArea = ee.Image.pixelArea();

  // Calculate water area within region
  function calculateWaterArea(waterMask) {
    const waterAreaImg = waterMask.multiply(pixelArea).divide(1000000); // Convert to km²
    const stats = waterAreaImg.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: trentRiver,
      scale: 100,
      maxPixels: 1e9,
      bestEffort: true
    });
    return stats.get('VV');
  }

  const baselineArea = calculateWaterArea(baselineWater).getInfo();
  const eventArea = calculateWaterArea(eventWater).getInfo();

  // Check for valid pixel counts (Case 2)
  if (baselineArea === null || eventArea === null) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  console.log(`Baseline water area: ${baselineArea.toFixed(2)} km²`);
  console.log(`Event water area: ${eventArea.toFixed(2)} km²`);

  // 5. Validation & Final Answer
  // Check for calculation failure (Case 3)
  if (!isFinite(baselineArea) || !isFinite(eventArea) || baselineArea < 0 || eventArea < 0) {
    console.log("Invalid area calculation.");
    console.log("<answer>C3</answer>");
    return;
  }

  // Determine flooding: significant increase in water area (>20%)
  const areaIncrease = ((eventArea - baselineArea) / baselineArea) * 100;
  console.log(`Water area change: ${areaIncrease.toFixed(1)}%`);

  // Threshold for flooding detection: >20% increase in water area
  const floodingThreshold = 20;

  if (areaIncrease > floodingThreshold) {
    console.log("<answer>A</answer>"); // Yes, flooding occurred
  } else {
    console.log("<answer>B</answer>"); // No significant flooding
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
